insert into public.curriculum_competencies (id, course_id, academic_level, competency_area_id, statement, status) values
  ('ug-aut200-engine-mechanical-diagnosis','aut-200','undergraduate',null,'Analyze advanced engine mechanical relationships, distinguish measured evidence from diagnosis, and identify the applicable service information required before specifications or procedures are used.','planned'),
  ('ug-aut201-engine-mechanical-lab','aut-201','undergraduate',null,'Organize engine mechanical laboratory evidence, select an appropriate measurement or inspection approach, and justify a next step using applicable specifications and documented observations.','planned'),
  ('ug-aut211-engine-performance-lab','aut-211','undergraduate',null,'Collect and interpret generalized engine-performance test evidence, preserve test context and units, and justify a diagnostic next step using applicable technical information.','planned'),
  ('ug-aut220-automatic-transmission-systems','aut-220','undergraduate',null,'Explain generalized automatic-transmission power-flow and control relationships, distinguish system evidence from conclusions, and identify applicable information required for diagnosis or service.','planned'),
  ('ug-aut230-automotive-electronics','aut-230','undergraduate',null,'Explain electronic signal and control relationships, interpret generalized sensor/actuator evidence, and use applicable technical information to justify a diagnostic next step.','planned'),
  ('ug-aut240-advanced-electrical-diagnosis','aut-240','undergraduate',null,'Analyze advanced electrical-system relationships, interpret measurements in operating context, and justify a next diagnostic action using applicable vehicle-specific information.','planned'),
  ('ug-aut250-systematic-diagnostics','aut-250','undergraduate',null,'Organize diagnostic evidence from symptoms, scan data, trouble codes, tests, and applicable information to justify and verify a systematic next diagnostic step.','planned'),
  ('ug-aut251-diagnostics-lab','aut-251','undergraduate',null,'Plan and document generalized fault-isolation work, collect relevant evidence, and justify a safe next test without substituting assumptions for verified vehicle information.','planned'),
  ('ug-aut260-vehicle-dynamics','aut-260','undergraduate',null,'Explain generalized vehicle-dynamics relationships, apply appropriate quantitative reasoning, and distinguish modeled behavior from vehicle-specific limits or measured evidence.','planned'),
  ('ug-aut270-emissions-systems','aut-270','undergraduate',null,'Explain emissions-system relationships, interpret generalized sensor and system evidence, and identify applicable technical or regulatory information required before diagnostic conclusions are made.','planned'),
  ('ug-aut280-control-systems','aut-280','undergraduate',null,'Explain generalized feedback and control relationships, interpret sensor/actuator evidence, and use applicable system information to justify a control-system diagnostic next step.','planned')
